"""Build facts-add files for chapter 14 (numbers lens) from compact specs.
Usage: python3 -I gen_prose.py <batch-name>   writes <batch-name>.json next to this script."""
import json, os, sys

HERE = os.path.dirname(os.path.abspath(__file__))
D = "docs/elasticloadbalancing/latest/"
URLS = {
    "www/elasticloadbalancing/faqs": "https://aws.amazon.com/elasticloadbalancing/faqs/",
    "www/elasticloadbalancing/pricing": "https://aws.amazon.com/elasticloadbalancing/pricing/",
    "www/elasticloadbalancing/features": "https://aws.amazon.com/elasticloadbalancing/features/",
}

def url(src):
    if src in URLS:
        return URLS[src]
    assert src.startswith("docs/")
    return "https://docs.aws.amazon.com/" + src[len("docs/"):] + ".html"

def ev(src, quote):
    s = src if src.startswith(("docs/", "www/")) else D + src
    return {"source_id": s, "url": url(s), "quote": quote, "table_header": None}

def fact(fid, kind, claim, q, vals, evidence, scope="", dom="", adj=False, cond="",
         bullets=("3.4.K3",), rel="extended", tier=1, tier0=False, vol="stable", note=None, hard=True):
    return {
        "id": fid, "service": "elb", "home_chapter": "14", "kind": kind,
        "claim": claim, "question": q,
        "values": [{"key": "v%d" % i, "display": d, "spoken": s} for i, (d, s) in enumerate(vals)],
        "qualifiers": {"scope": scope, "default_or_max": dom, "adjustable": adj, "condition": cond},
        "evidence": evidence,
        "source_tier": tier, "hard": hard, "tier0": tier0, "volatility": vol,
        "changed": None, "change_items": [], "bullets": list(bullets),
        "exam_relevance": rel, "note": note,
    }

